{"action":"write_file","path":"query.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parseQuery } = require('./query');

const plain = (o) => JSON.parse(JSON.stringify(o));

test('simple pairs and a leading question mark', () => {
  assert.deepEqual(plain(parseQuery('a=1&b=2')), { a: '1', b: '2' });
  assert.deepEqual(plain(parseQuery('?x=y')), { x: 'y' });
});

test('repeated keys become arrays', () => {
  assert.deepEqual(plain(parseQuery('a=1&a=2')), { a: ['1', '2'] });
});

test('empty segments and empty keys/values', () => {
  assert.deepEqual(plain(parseQuery('a=1&&b=2')), { a: '1', b: '2' });
  assert.deepEqual(plain(parseQuery('a=&b=c')), { a: '', b: 'c' });
  assert.deepEqual(plain(parseQuery('a')), { a: '' });
  assert.deepEqual(plain(parseQuery('=x&a=1')), { a: '1' });
  assert.deepEqual(plain(parseQuery('a=b=c')), { a: 'b=c' });
});

test('decoding plus and percent escapes', () => {
  assert.deepEqual(plain(parseQuery('a=hello+world')), { a: 'hello world' });
  assert.deepEqual(plain(parseQuery('a=%2B')), { a: '+' });
  assert.deepEqual(plain(parseQuery('a=%E2%82%AC')), { a: '€' });
  assert.deepEqual(plain(parseQuery('a=%zz%4%')), { a: '%zz%4%' });
});

test('type error on non-string', () => {
  assert.throws(() => parseQuery(123), TypeError);
  assert.throws(() => parseQuery(null), TypeError);
});

test('null prototype and key order', () => {
  const q = parseQuery('constructor=1&__proto__=2&a=3');
  assert.equal(Object.getPrototypeOf(q), null);
  assert.deepEqual(Object.keys(q), ['constructor', '__proto__', 'a']);
});
"}```

